def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal = []
    vertical = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                for rr, cc, value in ((r, c + 1, 5), (r, c + 2, 5),
                                      (r - 1, c + 2, 1)):
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
            elif color == 2:
                cells = [(r, x) for x in range(c - 4, c + 1)]
                horizontal.append(cells)
                for rr, cc in cells:
                    if 0 <= cc < w:
                        out[rr][cc] = 2 if cc in (c - 4, c) else 5
            elif color == 3:
                cells = [(x, c) for x in range(r, r + 4)]
                vertical.append(cells)
                for rr, cc in cells:
                    if 0 <= rr < h:
                        out[rr][cc] = 3 if rr in (r, r + 3) else 5
            elif color == 6:
                cells = [(x, c) for x in range(r - 6, r + 1)]
                vertical.append(cells)
                for rr, cc in cells:
                    if 0 <= rr < h:
                        out[rr][cc] = 6 if rr in (r - 6, r) else 5

    intersections = set()
    for hs in horizontal:
        for vs in vertical:
            intersections.update(set(hs) & set(vs))

    for r, c in intersections:
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 4
            rr, cc = r + 1, c - 1
            while rr < h and cc >= 0:
                out[rr][cc] = 4
                rr += 1
                cc -= 1

    return out
